// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func roundScanMapperNullable(prefix string) scan.Mapper[*Round] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*Round, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *roundPreloadBuf) any
		}
		targets := make([]target, 0, 10)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *roundPreloadBuf) any { return &b.ID }})
			case "match_id":
				targets = append(targets, target{i, func(b *roundPreloadBuf) any { return &b.MatchID }})
			case "index":
				targets = append(targets, target{i, func(b *roundPreloadBuf) any { return &b.Index }})
			case "definition_version_id":
				targets = append(targets, target{i, func(b *roundPreloadBuf) any { return &b.DefinitionVersionID }})
			case "status":
				targets = append(targets, target{i, func(b *roundPreloadBuf) any { return &b.Status }})
			case "started_at":
				targets = append(targets, target{i, func(b *roundPreloadBuf) any { return &b.StartedAt }})
			case "ended_at":
				targets = append(targets, target{i, func(b *roundPreloadBuf) any { return &b.EndedAt }})
			case "map_id":
				targets = append(targets, target{i, func(b *roundPreloadBuf) any { return &b.MapID }})
			case "map_seed":
				targets = append(targets, target{i, func(b *roundPreloadBuf) any { return &b.MapSeed }})
			case "stats_ref":
				targets = append(targets, target{i, func(b *roundPreloadBuf) any { return &b.StatsRef }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(roundPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*Round, error) {
				buf := link.(*roundPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.IsValue()) &&
					!(buf.MatchID.IsValue()) &&
					!(buf.Index.IsValue()) &&
					!(buf.DefinitionVersionID.IsValue()) &&
					!(buf.Status.IsValue()) &&
					!(buf.StartedAt.IsValue()) &&
					!(buf.EndedAt.IsValue()) &&
					!(buf.MapID.IsValue()) &&
					!(buf.MapSeed.IsValue()) &&
					!(buf.StatsRef.IsValue()) {
					return nil, nil
				}

				o := new(Round)
				if buf.ID.IsValue() {
					o.ID = buf.ID.MustGet()
				}
				if buf.MatchID.IsValue() {
					o.MatchID = buf.MatchID.MustGet()
				}
				if buf.Index.IsValue() {
					o.Index = buf.Index.MustGet()
				}
				if buf.DefinitionVersionID.IsValue() {
					o.DefinitionVersionID = buf.DefinitionVersionID.MustGet()
				}
				if buf.Status.IsValue() {
					o.Status = buf.Status.MustGet()
				}
				if buf.StartedAt.IsValue() {
					o.StartedAt = buf.StartedAt.MustGet()
				}
				if buf.EndedAt.IsValue() {
					o.EndedAt = buf.EndedAt.MustGet()
				}
				o.MapID = buf.MapID
				o.MapSeed = buf.MapSeed
				o.StatsRef = buf.StatsRef
				return o, nil
			}
	}
}

func (o *Round) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "RoundPlayers":
		rels, ok := retrieved.(RoundPlayerSlice)
		if !ok {
			return fmt.Errorf("round cannot load %T as %q", retrieved, name)
		}

		o.R.RoundPlayers = rels
		o.R.Loaded.RoundPlayers = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Round = o
				rel.R.Loaded.Round = true
			}
		}
		return nil
	case "RoundTeams":
		rels, ok := retrieved.(RoundTeamSlice)
		if !ok {
			return fmt.Errorf("round cannot load %T as %q", retrieved, name)
		}

		o.R.RoundTeams = rels
		o.R.Loaded.RoundTeams = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Round = o
				rel.R.Loaded.Round = true
			}
		}
		return nil
	case "DefinitionVersion":
		rel, ok := retrieved.(*DefinitionVersion)
		if !ok {
			return fmt.Errorf("round cannot load %T as %q", retrieved, name)
		}

		o.R.DefinitionVersion = rel
		o.R.Loaded.DefinitionVersion = true

		if rel != nil {
			rel.R.Rounds = RoundSlice{o}
		}
		return nil
	case "Match":
		rel, ok := retrieved.(*Match)
		if !ok {
			return fmt.Errorf("round cannot load %T as %q", retrieved, name)
		}

		o.R.Match = rel
		o.R.Loaded.Match = true

		if rel != nil {
			rel.R.Rounds = RoundSlice{o}
		}
		return nil
	case "StatRecords":
		rels, ok := retrieved.(StatRecordSlice)
		if !ok {
			return fmt.Errorf("round cannot load %T as %q", retrieved, name)
		}

		o.R.StatRecords = rels
		o.R.Loaded.StatRecords = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Round = o
				rel.R.Loaded.Round = true
			}
		}
		return nil
	case "StatValues":
		rels, ok := retrieved.(StatValueSlice)
		if !ok {
			return fmt.Errorf("round cannot load %T as %q", retrieved, name)
		}

		o.R.StatValues = rels
		o.R.Loaded.StatValues = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Round = o
				rel.R.Loaded.Round = true
			}
		}
		return nil
	default:
		return fmt.Errorf("round has no relationship %q", name)
	}
}

type roundPreloader struct {
	DefinitionVersion func(...psql.PreloadOption) psql.Preloader
	Match             func(...psql.PreloadOption) psql.Preloader
}

func buildRoundPreloader() roundPreloader {
	return roundPreloader{
		DefinitionVersion: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*DefinitionVersion, DefinitionVersionSlice](psql.PreloadRel{
				Name: "DefinitionVersion",
				Sides: []psql.PreloadSide{
					{
						From:        Rounds,
						To:          DefinitionVersions,
						FromColumns: []string{"definition_version_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, DefinitionVersions.Columns.Names(), definitionVersionScanMapperNullable, opts...)
		},
		Match: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Match, MatchSlice](psql.PreloadRel{
				Name: "Match",
				Sides: []psql.PreloadSide{
					{
						From:        Rounds,
						To:          Matches,
						FromColumns: []string{"match_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Matches.Columns.Names(), matchScanMapperNullable, opts...)
		},
	}
}

type roundThenLoader[Q orm.Loadable] struct {
	RoundPlayers      func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	RoundTeams        func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	DefinitionVersion func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Match             func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	StatRecords       func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	StatValues        func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildRoundThenLoader[Q orm.Loadable]() roundThenLoader[Q] {
	type RoundPlayersLoadInterface interface {
		LoadRoundPlayers(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type RoundTeamsLoadInterface interface {
		LoadRoundTeams(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type DefinitionVersionLoadInterface interface {
		LoadDefinitionVersion(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type MatchLoadInterface interface {
		LoadMatch(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type StatRecordsLoadInterface interface {
		LoadStatRecords(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type StatValuesLoadInterface interface {
		LoadStatValues(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return roundThenLoader[Q]{
		RoundPlayers: thenLoadBuilder[Q](
			"RoundPlayers",
			func(ctx context.Context, exec bob.Executor, retrieved RoundPlayersLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadRoundPlayers(ctx, exec, mods...)
			},
		),
		RoundTeams: thenLoadBuilder[Q](
			"RoundTeams",
			func(ctx context.Context, exec bob.Executor, retrieved RoundTeamsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadRoundTeams(ctx, exec, mods...)
			},
		),
		DefinitionVersion: thenLoadBuilder[Q](
			"DefinitionVersion",
			func(ctx context.Context, exec bob.Executor, retrieved DefinitionVersionLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadDefinitionVersion(ctx, exec, mods...)
			},
		),
		Match: thenLoadBuilder[Q](
			"Match",
			func(ctx context.Context, exec bob.Executor, retrieved MatchLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadMatch(ctx, exec, mods...)
			},
		),
		StatRecords: thenLoadBuilder[Q](
			"StatRecords",
			func(ctx context.Context, exec bob.Executor, retrieved StatRecordsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadStatRecords(ctx, exec, mods...)
			},
		),
		StatValues: thenLoadBuilder[Q](
			"StatValues",
			func(ctx context.Context, exec bob.Executor, retrieved StatValuesLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadStatValues(ctx, exec, mods...)
			},
		),
	}
}

// LoadRoundPlayers loads the round's RoundPlayers into the .R struct
func (o *Round) LoadRoundPlayers(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.RoundPlayers = nil
	o.R.Loaded.RoundPlayers = false

	related, err := o.RoundPlayers(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.Round = o
		rel.R.Loaded.Round = true
	}

	o.R.RoundPlayers = related
	o.R.Loaded.RoundPlayers = true
	return nil
}

// LoadRoundPlayers loads the round's RoundPlayers into the .R struct
func (os RoundSlice) LoadRoundPlayers(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	roundPlayers, err := os.RoundPlayers(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.RoundPlayers = nil
		o.R.Loaded.RoundPlayers = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	roundByKey := make(map[int64][]*Round, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		roundByKey[o.ID] = append(roundByKey[o.ID], o)
	}

	for _, rel := range roundPlayers {

		owners, ok := roundByKey[rel.RoundID]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.Round = o
			rel.R.Loaded.Round = true

			o.R.RoundPlayers = append(o.R.RoundPlayers, rel)

		}
	}

	return nil
}

