// LoadDefinitionVersion loads the round's DefinitionVersion into the .R struct
func (os RoundSlice) LoadDefinitionVersion(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	definitionVersions, err := os.DefinitionVersion(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.DefinitionVersion = nil
		o.R.Loaded.DefinitionVersion = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	roundByKey := make(map[int64][]*Round, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		roundByKey[o.DefinitionVersionID] = append(roundByKey[o.DefinitionVersionID], o)
	}

	for _, rel := range definitionVersions {

		owners, ok := roundByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.DefinitionVersion != nil {
				continue
			}

			rel.R.Rounds = append(rel.R.Rounds, o)

			o.R.DefinitionVersion = rel

		}
	}

	return nil
}

