type roundCountThenLoader[Q orm.Loadable] struct {
	RoundPlayers func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	RoundTeams   func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	StatRecords  func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	StatValues   func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildRoundCountThenLoader[Q orm.Loadable]() roundCountThenLoader[Q] {
	type RoundPlayersCountInterface interface {
		LoadCountRoundPlayers(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type RoundTeamsCountInterface interface {
		LoadCountRoundTeams(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type StatRecordsCountInterface interface {
		LoadCountStatRecords(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type StatValuesCountInterface interface {
		LoadCountStatValues(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return roundCountThenLoader[Q]{
		RoundPlayers: countThenLoadBuilder[Q](
			"RoundPlayers",
			func(ctx context.Context, exec bob.Executor, retrieved RoundPlayersCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountRoundPlayers(ctx, exec, mods...)
			},
		),
		RoundTeams: countThenLoadBuilder[Q](
			"RoundTeams",
			func(ctx context.Context, exec bob.Executor, retrieved RoundTeamsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountRoundTeams(ctx, exec, mods...)
			},
		),
		StatRecords: countThenLoadBuilder[Q](
			"StatRecords",
			func(ctx context.Context, exec bob.Executor, retrieved StatRecordsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountStatRecords(ctx, exec, mods...)
			},
		),
		StatValues: countThenLoadBuilder[Q](
			"StatValues",
			func(ctx context.Context, exec bob.Executor, retrieved StatValuesCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountStatValues(ctx, exec, mods...)
			},
		),
	}
}

// LoadCountRoundPlayers loads the count of RoundPlayers into the C struct
func (o *Round) LoadCountRoundPlayers(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	count, err := o.RoundPlayers(mods...).Count(ctx, exec)
	if err != nil {
		return err
	}

	o.C.RoundPlayers = &count
	return nil
}

// LoadCountRoundPlayers loads the count of RoundPlayers for a slice in a single batch query
func (os RoundSlice) LoadCountRoundPlayers(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs

	pkID := make(pgtypes.Array[int64], 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		pkID = append(pkID, o.ID)
	}
	PKArgExpr := psql.Any(psql.Cast(psql.Arg(pkID), "bigint[]"))

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		ID    int64
		Count int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			RoundPlayers.Columns.RoundID.As("id"),
			psql.Raw("count(*) as count"),
		),
		// Single-hop: FROM related table directly
		sm.From(RoundPlayers.NameAsExpr()),

		// WHERE fk IN (parent PKs) — psql single-column FK uses `= ANY(array)` (see PKArgExpr above)
		sm.Where(RoundPlayers.Columns.RoundID.EQ(PKArgExpr)),
		// GROUP BY fk columns
		sm.GroupBy(RoundPlayers.Columns.RoundID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		psql.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Single-column FK: direct map lookup
	countMap := make(map[int64]int64, len(results))
	for _, r := range results {
		countMap[r.ID] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[o.ID]
		o.C.RoundPlayers = &count
	}

	return nil
}

