type roundJoins[Q dialect.Joinable] struct {
	typ               string
	RoundPlayers      modAs[Q, roundPlayerColumns]
	RoundTeams        modAs[Q, roundTeamColumns]
	DefinitionVersion modAs[Q, definitionVersionColumns]
	Match             modAs[Q, matchColumns]
	StatRecords       modAs[Q, statRecordColumns]
	StatValues        modAs[Q, statValueColumns]
}

func (j roundJoins[Q]) aliasedAs(alias string) roundJoins[Q] {
	return buildRoundJoins[Q](buildRoundColumns(alias), j.typ)
}

func buildRoundJoins[Q dialect.Joinable](cols roundColumns, typ string) roundJoins[Q] {
	return roundJoins[Q]{
		typ: typ,
		RoundPlayers: modAs[Q, roundPlayerColumns]{
			c: RoundPlayers.Columns,
			f: func(to roundPlayerColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, RoundPlayers.NameExpr().As(to.Alias())).On(
						to.RoundID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		RoundTeams: modAs[Q, roundTeamColumns]{
			c: RoundTeams.Columns,
			f: func(to roundTeamColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, RoundTeams.NameExpr().As(to.Alias())).On(
						to.RoundID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		DefinitionVersion: modAs[Q, definitionVersionColumns]{
			c: DefinitionVersions.Columns,
			f: func(to definitionVersionColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, DefinitionVersions.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.DefinitionVersionID),
					))
				}

				return mods
			},
		},
		Match: modAs[Q, matchColumns]{
			c: Matches.Columns,
			f: func(to matchColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Matches.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.MatchID),
					))
				}

				return mods
			},
		},
		StatRecords: modAs[Q, statRecordColumns]{
			c: StatRecords.Columns,
			f: func(to statRecordColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, StatRecords.NameExpr().As(to.Alias())).On(
						to.RoundID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		StatValues: modAs[Q, statValueColumns]{
			c: StatValues.Columns,
			f: func(to statValueColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, StatValues.NameExpr().As(to.Alias())).On(
						to.RoundID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
